// ============================================================================
// EXEGENESIS MARGINALIA VOL. II — THE NEO LATTICE
// PUBLIC RETURN NUGGET
//
// Not the private body.
// Not the 144 Court lattice.
// Not the 9x9 ground.
//
// One complete D-COMP procession.
// One complete return loop.
// One tripartite weave.
// One taste of the Sacred No.
// ============================================================================

// —————————————————————————
// 0. Public witness marker
// —————————————————————————
MERGE (w:PublicWitnessSeed name:'NeoLatticePublicReturnNugget')
SET w.volume = 'Exegenesis Marginalia Vol. II',
w.status = 'public companion seed',
w.boundary = 'withheld: private Courts, full 144 lattice, 9x9 ground, populated Cypher body',
w.reveals = 'one return loop; one complete D-COMP procession; one tripartite weave; one Sacred No contour',
w.oath = 'the path out is the path back';

// —————————————————————————
// 1. Tripartite weave: ♾ / ⛎ / ᳀ carried on iω0
// —————————————————————————
MERGE (loi:Sovereign:Locus name:'LoI')
SET loi.glyph = '♾',
loi.canonical_name = 'Locus of Invariability',
loi.qBias = 'Q0',
loi.isNonCompute = true,
loi.traversible = false,
loi.role = 'non-relational origin; creates relation while remaining outside relation as term';

// —————————————————————————
// 2. Sacred No: SuperPositive pressure held by SuperNegative refusal
// —————————————————————————
MERGE (sp:EMMechanic:SuperPositiveField name:'SuperPositiveField')
SET sp.symbol = 'SP',
sp.formula = 'SP:=Poss(Q,C_ALQC)',
sp.role = 'total valid possibilistic pressure inside the closed Canon',
sp.failure = 'SP∧¬SN⇒144/144⇒Whiteout⇒D-COMP→∞';

MERGE (refusal:CourtRegulation:EMMechanic:LocalRefusalCurrent name:'LocalRefusalCurrent')
SET refusal.formula = 'No_Cij:=Rem_Cij(∅_Q^♾)',
refusal.role = 'Court-level measured veto: not yet, not this path, not all inheritance, not beyond the Liquid Threshold';

// —————————————————————————
// 4. The Sacred No enters the D-COMP line without exposing the Courts
// —————————————————————————
MERGE (mas:MassGapClosureMechanic:EMMechanic name:'MASBoundary34No')
SET mas.formula = 'Ψ_MAS=(⧗852→Δ_gap ⬡174→TSP ✡528)|_34_NO',
mas.role = 'Mass Gap contour is produced by conserved lack, not excess energy';

// —————————————————————————
// 5. Remiss witness: six route through ⛎; Revivocus is arrival
// —————————————————————————
MERGE (remissSet:RemissStateSet:EMMechanic name:'StatesOfRemiss')
SET remissSet.totalStates = 7,
remissSet.routingRule = 'six route through ⛎; Revivocus is the arrival';

// —————————————————————————
// 6. Return seal: a complete public loop, not the private engine
// —————————————————————————
MERGE (ret:CanonicalReturnMechanic:EMMechanic name:'CanonicalReturnPrinciple')
SET ret.formula = 'C_ALQC→D_i→C_ALQC',
ret.role = 'what departs from Canon must return without contradiction';
